"""Myofunctional specialist routing on existing pages. Exact preflight, backup and rollback."""
import argparse,base64,fcntl,hashlib,json,os,shutil,socket,subprocess,sys,tempfile,zlib
from pathlib import Path
from datetime import datetime,timezone
import re
CSS='''
.az-chat{box-sizing:border-box;max-width:1120px;margin:24px auto;padding:18px 20px;background:#f4faff;border:1px solid #dce8f2;border-radius:8px;font-family:Montserrat,Arial,sans-serif;color:#21445e;clear:both}
.az-chat *{box-sizing:border-box}.az-chat h2{font-size:22px;line-height:1.3;color:#2080c4;margin:0 0 12px;padding-left:12px;border-left:3px solid #debc19}.az-chat-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.az-chat-card{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 16px;background:#fff;border:1px solid #b9d9ef;border-radius:6px;min-width:0}.az-chat-link{display:inline-flex;align-items:center;gap:10px;color:#1268a7!important;font-size:16px;font-weight:700;line-height:1.4;text-decoration:none!important}.az-chat-link:hover{text-decoration:underline!important}.az-chat-link:focus-visible,.az-chat summary:focus-visible{outline:3px solid #debc19;outline-offset:4px}.az-chat-icon{display:inline-grid;place-items:center;width:36px;height:36px;border-radius:8px;flex-shrink:0;background:#2080c4;color:#fff;font-size:22px}.az-chat-max .az-chat-icon{background:#6955b8;font-size:13px}.az-chat-qr{flex-shrink:0;text-align:center}.az-chat-qr summary{display:none}.az-chat-qr img{display:block!important;width:104px!important;height:104px!important;max-width:none!important;object-fit:contain!important;margin:0 auto!important;background:#fff!important;border:0!important;border-radius:0!important}.az-chat-qr p{font-size:11px!important;line-height:1.3!important;margin:4px 0 0!important;color:#526b7d}.az-chat-note{margin:10px 0 0;font-size:13px;line-height:1.5;color:#526b7d}
@media(max-width:700px){.az-chat{margin:16px 12px;padding:14px 12px}.az-chat h2{font-size:20px;margin-bottom:10px}.az-chat-grid{grid-template-columns:1fr;gap:8px}.az-chat-card{flex-wrap:wrap;padding:10px 12px;gap:8px}.az-chat-link{font-size:15px;flex:1}.az-chat-icon{width:30px;height:30px}.az-chat-qr summary{display:block;cursor:pointer;color:#1268a7;font-size:13px;padding:8px 4px}.az-chat-qr[open]{width:100%}.az-chat-qr img{width:144px!important;height:144px!important}.az-chat-note{font-size:12px}}
'''
BLOCK='''<section class="az-chat" aria-labelledby="az-chat-title"><h2 id="az-chat-title">Напишите нам</h2><div class="az-chat-grid">'''
for cls,label,url,icon in [('telegram','Telegram','https://t.me/AZ_nsk_bot','➤'),('max','MAX','https://max.ru/id5406800409_bot','MAX')]:
 BLOCK+=f'''<div class="az-chat-card az-chat-{cls}"><a class="az-chat-link" href="{url}" target="_blank" rel="noopener" data-az-messenger="{cls}"><span class="az-chat-icon" aria-hidden="true">{icon}</span>Напишите нам в {label}</a><details class="az-chat-qr" open><summary>QR-код {label}</summary><img src="/assets/az-chat-{cls}-20261026.svg" width="104" height="104" alt="QR-код чата клиники в {label}" loading="lazy"><p>Наведите камеру телефона</p></details></div>'''
BLOCK+='</div><p class="az-chat-note">Администратор поможет с записью и вопросами о приёме.</p></section>'
JS="""(()=>{const q=matchMedia('(max-width:700px)');function sync(){document.querySelectorAll('.az-chat-qr').forEach(d=>d.open=!q.matches)}sync();q.addEventListener('change',sync);document.addEventListener('click',e=>{const a=e.target.closest('a[data-az-messenger]');if(a&&typeof window.ym==='function')window.ym(113776005,'reachGoal','messenger_'+a.dataset.azMessenger)})})();"""
def transform(s):
 assert 'id="az-chat-title"' not in s
 s=re.sub(r'https?://(?:t\.me|telegram\.me)/azmednsk/?(?=["\s<])','https://t.me/AZ_nsk_bot',s,flags=re.I)
 # Existing navigation/contact links remain in place; the new shared block supplies both bots.
 m=re.search(r'<footer\b|<section\b[^>]*\bid="layout-2489767221"',s)
 if not m:
  m=re.search(r'</main>',s)
 assert m, 'No footer/main insertion point'
 s=s[:m.start()]+BLOCK+s[m.start():]
 assert '</head>' in s and '</body>' in s
 s=s.replace('</head>','<link rel="stylesheet" href="/assets/az-chat-20261026.css"></head>')
 return s.replace('</body>','<script src="/assets/az-chat-20261026.js" defer></script></body>')

